function firstPair(values, target) {
  const seen = new Map()
  for (let i = 0; i < values.length; i += 1) {
    const need = target - values[i]
    if (seen.has(need)) return [seen.get(need), i]
    seen.set(values[i], i)
  }
  return [-1, -1]
}

